import React, { useContext, useState } from 'react';
import { AppContext } from '../context/AppContext';
import BookList from '../components/BookList';

const BooksPage = () => {
  const { books, loading, error } = useContext(AppContext);
  const [search, setSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);

  const categories = [...new Set(books.map(book => book.category))];

  const filteredBooks = books.filter(book => {
    const matchesSearch = book.title.toLowerCase().includes(search.toLowerCase()) ||
                         book.author.toLowerCase().includes(search.toLowerCase()) ||
                         book.category.toLowerCase().includes(search.toLowerCase());
    const matchesCategory = selectedCategory === '' || book.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  const searchSuggestions = search ? [
    ...books.filter(book => 
      book.title.toLowerCase().includes(search.toLowerCase()) ||
      book.author.toLowerCase().includes(search.toLowerCase())
    ).slice(0, 3),
    ...categories.filter(category => 
      category.toLowerCase().includes(search.toLowerCase())
    ).map(category => ({ isCategory: true, category }))
  ].slice(0, 5) : [];

  return (
    <div className="max-w-7xl mx-auto py-8 px-4">
      <h1 className="text-3xl font-bold mb-6 text-gray-800">All Books</h1>

      <div className="mb-6">
        <div className="relative mb-4">
          <input
            type="text"
            placeholder="Search books or categories..."
            value={search}
            onChange={(e) => {
              setSearch(e.target.value);
              setShowSuggestions(e.target.value.length > 0);
            }}
            onFocus={() => setShowSuggestions(search.length > 0)}
            onBlur={() => setTimeout(() => setShowSuggestions(false), 200)}
            className="w-full p-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          />

          {showSuggestions && searchSuggestions.length > 0 && (
            <div className="absolute top-full left-0 right-0 bg-white border border-gray-300 rounded-lg shadow-lg z-10 mt-1">
              {searchSuggestions.map((item, index) => (
                <div
                  key={item.isCategory ? item.category : item._id}
                  className="p-3 hover:bg-gray-100 cursor-pointer border-b border-gray-100 last:border-b-0"
                  onClick={() => {
                    if (item.isCategory) {
                      setSelectedCategory(item.category);
                      setSearch('');
                    } else {
                      setSearch(item.title);
                    }
                    setShowSuggestions(false);
                  }}
                >
                  {item.isCategory ? (
                    <>
                      <div className="font-semibold text-blue-600 flex items-center">
                        <span className="mr-2">📚</span> Category: {item.category}
                      </div>
                      <div className="text-sm text-gray-500">Click to filter by this category</div>
                    </>
                  ) : (
                    <>
                      <div className="font-semibold text-gray-800">{item.title}</div>
                      <div className="text-sm text-gray-600">by {item.author} • {item.category}</div>
                    </>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="flex flex-wrap gap-2">
          <button
            onClick={() => setSelectedCategory('')}
            className={`px-4 py-2 rounded-full text-sm font-medium transition-colors ${
              selectedCategory === '' 
                ? 'bg-blue-500 text-white' 
                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
            }`}
          >
            All Categories
          </button>
          {categories.map(category => (
            <button
              key={category}
              onClick={() => setSelectedCategory(category)}
              className={`px-4 py-2 rounded-full text-sm font-medium transition-colors ${
                selectedCategory === category 
                  ? 'bg-blue-500 text-white' 
                  : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
              }`}
            >
              {category}
            </button>
          ))}
        </div>
      </div>

      {loading && <p className="text-center">Loading...</p>}
      {error && <p className="text-red-500 text-center">{error}</p>}
      <BookList books={filteredBooks} />
    </div>
  );
};

export default BooksPage;
